 @Test void permissionLossForConfigureAndSourceDoesNotPreventReadAuthorizedCancellation()throws Exception{scoped(()->{when(resources.require(eq(a),any(),eq("capability.configure"),anyString())).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));when(deps.require(eq(a),any(),any(),anyString())).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));assertEquals("CANCELLED",cancel(capability()).path("status").asText());verify(deps,never()).require(eq(a),any(),any(),anyString());return null;});}
